                        new floatBcglsInvoker { TolValue = Consts.floatSqrtEps, MaxIterMul = 20 },
                        new floatLsmrInvoker { TolValue = Consts.floatSqrtEps, MaxIterMul = 20 },
                        strictConsistentStatus: true, skipNarrow: false);
